import java.io.*;import java.util.*;import java.util.stream.*;class Result {public static int sherlockAndAnagrams(String s) {Map<String, Integer> map = new HashMap<>();int n = s.length();int count = 0;for (int i = 0; i < n; i++) {for (int j = i + 1; j <= n; j++) {String sub = s.substring(i, j);char[] chars = sub.toCharArray();Arrays.sort(chars);String key = new String(chars);int val = map.getOrDefault(key, 0);count += val;map.put(key, val + 1);}}return count;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));int q = Integer.parseInt(bufferedReader.readLine().trim());IntStream.range(0, q).forEach(qItr -> {try {String s = bufferedReader.readLine();int result = Result.sherlockAndAnagrams(s);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();} catch (IOException ex) {throw new RuntimeException(ex);}});bufferedReader.close();bufferedWriter.close();}}